#include <LVUI/Compiler.h>
#include <iostream>
#include <stdexcept>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
std::string compile(std::string_view source){auto result=lvui::compile_native(source,{.framework="LVRS"});if(!result)throw std::runtime_error(result.error().message);return *result;}
void defaults(){auto code=compile("Window { ProgressBar() }");check(code.find("lvrs::ProgressBar::create")!=code.npos,"LVRS ProgressBar still uses the generic iiGUI primitive");}
void inputs(){auto code=compile("Window { ProgressBar(minimumValue: 100, endValue: 0, startValue: 80, currentValue: 20, size: .regular, shapeStyle: .shapeCylinder, regularHeight: 4, largeHeight: 8, cornerRadius: 12, width: 300, height: 9, trackColor: Color(0,0,0,.1), fillColor: .primary, motionEnabled: false, displayedStart: .2, displayedProgress: .5, minimumValueStateKey: \"lo\", maximumValueStateKey: \"hi\", startValueStateKey: \"begin\", currentValueStateKey: \"done\") }");check(code.find("ProgressShape::cylinder")!=code.npos&&code.find("ProgressSize::regular")!=code.npos&&code.find(".displayed_progress")!=code.npos,"Original ProgressBar inputs were lost");}
void reactive(){auto code=compile("import vm Backend\nWindow { ProgressBar(minimumValue: vm.low, maximumValue: vm.high, startValue: vm.start, currentValue: vm.current, stateModel: vm.state, size: vm.size, shapeStyle: vm.shape, motion: vm.motion, motionEnabled: vm.motionEnabled, width: vm.width, height: vm.height, cornerRadius: vm.radius, trackColor: vm.track, fillColor: vm.fill, displayedProgress: vm.displayed) }");check(code.find("progress_source(scope,")!=code.npos&&code.find("progress_size(")!=code.npos&&code.find("progress_shape(")!=code.npos&&code.find("component.set_options(value)")!=code.npos,"Reactive ProgressBar bypassed its retained native component");}
void scoped(){auto code=compile("import state lvrs.StateModel\nlet Bar: View = ProgressBar(stateModel: state)\nWindow { Bar() }");check(code.find("progress_source(scope, scope->")!=code.npos,"A directly imported state source was copied or lost its owner");}
void diagnostics(){for(auto source:{"Window { ProgressBar(maximumValue: 1, endValue: 2) }","Window { ProgressBar(size: .unknown) }","Window { ProgressBar(shapeStyle: 3) }","Window { ProgressBar(width: -1) }","Window { ProgressBar(motionEnabled: 3) }","Window { ProgressBar(progress: .5) }"}){auto result=lvui::compile_native(source,{.framework="LVRS"});check(!result&&result.error().line>0,"Invalid ProgressBar input lost its source diagnostic");}}
}
int main(int argc,char** argv){try{std::string name=argc>1?argv[1]:"defaults";if(name=="defaults")defaults();else if(name=="inputs")inputs();else if(name=="reactive")reactive();else if(name=="scoped")scoped();else if(name=="diagnostics")diagnostics();else throw std::runtime_error("Unknown ProgressBar compiler case");std::cout<<"ProgressBar compiler "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
